"""Fast exact primality test for 0 <= n <= 10**18, Codon 0.19.3.

Uses the FJ64_16k witness table and hash of Forisek and Jancina:
https://ceur-ws.org/Vol-1326/020-Forisek.pdf
The packed witness constants were transcribed from the public submission
https://judge.yosupo.jp/submission/252404; this implementation is independent.
The byte literal is used to avoid a very slow Codon compile of a 16k-element list.
"""

class Montgomery:
    """64-bit Montgomery residues for odd moduli at most 10**18."""
    n: u64
    neg_inv: u64
    one: u64
    r2: u64

    def __init__(self, n: int):
        self.n = u64(n)
        x = u64(1)
        for _ in range(6):
            x *= u64(2) - self.n * x
        self.neg_inv = u64(0) - x
        self.one = u64((u128(1) << u128(64)) % u128(self.n))
        self.r2 = u64(u128(self.one) * u128(self.one) % u128(self.n))

    def mul(self, a: u64, b: u64) -> u64:
        # The bound n <= 10**18 keeps t + m*n below 2**128.
        t = u128(a) * u128(b)
        m = u64(t) * self.neg_inv
        result = u64((t + u128(m) * u128(self.n)) >> u128(64))
        if result >= self.n:
            result -= self.n
        return result

    def encode(self, a: u64) -> u64:
        return self.mul(a, self.r2)

    def pow(self, a: u64, e: int) -> u64:
        out = self.one
        while e:
            if e & 1:
                out = self.mul(out, a)
            a = self.mul(a, a)
            e >>= 1
        return out

