def _sprp(ctx: Montgomery, a: int, d: int, s: int) -> bool:
    n = int(ctx.n)
    a %= n
    if a == 0:
        return True
    x = ctx.pow(ctx.encode(u64(a)), d)
    if x == ctx.one or x == ctx.n - ctx.one:
        return True
    for _ in range(s-1):
        x = ctx.mul(x, x)
        if x == ctx.n - ctx.one:
            return True
    return False

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n > 10**18:
        raise ValueError("n must be <= 10**18")
    for p in (2,3,5,7):
        if n==p:return True
        if n%p==0:return False
    if n < 121:return True
    s = (n-1).__cttz__()
    d = (n-1)>>s
    ctx=Montgomery(n)
    if not _sprp(ctx,2,d,s):return False
    h=u64(n)
    h=((h>>u64(32))^h)*u64(0x45d9f3b3335b369)
    h=((h>>u64(32))^h)*u64(0x3335b36945d9f3b)
    h=(h>>u64(32))^h
    i=int(h&u64(16383))*3
    b=ord(BASE_BYTES[i]) | (ord(BASE_BYTES[i+1]) << 8) | (ord(BASE_BYTES[i+2]) << 16)
    return _sprp(ctx,b&4095,d,s) and _sprp(ctx,b>>12,d,s)
